#include <AYEntity/DeterministicRigidBody3D.h>
#include <AYEntity/DeterministicRollback.h>
#include <iostream>
using namespace ayt::entity;using D=ayt::math::DetFloat32;using V=ayt::math::DetVec3;using Q=ayt::math::DetQuaternion;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
D ratio(int a,int b){return D::fromInt(a)/D::fromInt(b);}D abs(D x){return x.signBit()?-x:x;}
void near(D value,D expected,D tolerance=ratio(1,10000)){require(abs(value-expected)<=tolerance,"independent physical reference");}
V position(const DetSessionCheckpoint& cp,SimEntityId id){return V::fromBits(cp.actors.at(id).pose.position);}
V state(const DetSessionCheckpoint& cp,SimEntityId id,const DetRigidBody3DConfig& c,unsigned field){DetStateLayout layout(detRigidBodySchema3D(c));return std::get<V>(layout.read(cp.actors.at(id).blocks.at(c.bodySchema),field));}
void advance(DeterministicSession& s,unsigned count){for(unsigned i=0;i<count;++i)if(!s.advance({s.nextTick(),1,{}}))throw std::runtime_error(s.error());}
DetRigidBody3D sphere(D r,bool dynamic=false){DetRigidBody3D b;b.shape=DetRigidShape3D::Sphere;b.half={r,r,r};b.friction=D{};b.mass=dynamic?D::fromInt(1):D{};b.mode=dynamic?DetRigidMode3D::Dynamic:DetRigidMode3D::Static;return b;}
DetRigidBody3D capsule(D r,D h,bool dynamic=false){auto b=sphere(r,dynamic);b.shape=DetRigidShape3D::Capsule;b.half={r,h,r};return b;}
DetRigidBody3D box(V half,bool dynamic=false){DetRigidBody3D b;b.half=half;b.friction=D{};b.mass=dynamic?D::fromInt(1):D{};b.mode=dynamic?DetRigidMode3D::Dynamic:DetRigidMode3D::Static;return b;}
DetSessionConfig sessionConfig(){return {82,1,1,64,790082};}
void capsuleGeometry(){DetRigidBody3DConfig c;c.gravity={};
    DeterministicSession s(sessionConfig());require(installDetRigidBody3D(s,c),"capsule install");require(s.addEntity(1,detRigidBodyActor3D(c,capsule(ratio(1,2),D::fromInt(1))))&&s.addEntity(2,detRigidBodyActor3D(c,sphere(ratio(1,2)),{ratio(3,4),ratio(1,2),D{}}))&&s.seal(),"capsule sphere setup");
    auto ct=detRigidContacts3D(*s.checkpoint(),c);require(ct.size()==1&&ct[0].normal==V::fromInts(1,0,0),"capsule segment sphere normal");near(ct[0].penetration,ratio(1,4));
    auto quarter=Q::fromAxisSinCos(V::fromInts(0,0,1),D::fromInt(1),D::fromInt(1));require(bool(quarter),"capsule orientation");
    DeterministicSession cross(sessionConfig());require(installDetRigidBody3D(cross,c)&&cross.addEntity(1,detRigidBodyActor3D(c,capsule(ratio(1,2),D::fromInt(1))))&&cross.addEntity(2,detRigidBodyActor3D(c,capsule(ratio(1,2),D::fromInt(1)),{D{},D{},ratio(3,4)},*quarter))&&cross.seal(),"cross capsule setup");
    ct=detRigidContacts3D(*cross.checkpoint(),c);require(ct.size()==1&&ct[0].normal==V::fromInts(0,0,1),"skew capsule actual3D normal");near(ct[0].penetration,ratio(1,4));
    DeterministicSession shaft(sessionConfig());require(installDetRigidBody3D(shaft,c)&&shaft.addEntity(1,detRigidBodyActor3D(c,capsule(ratio(3,10),D::fromInt(1)),{D{},ratio(45,100),D{}},*quarter))&&shaft.addEntity(2,detRigidBodyActor3D(c,box({ratio(1,5),ratio(1,5),ratio(1,5)})))&&shaft.seal(),"shaft box setup");
    ct=detRigidContacts3D(*shaft.checkpoint(),c);require(ct.size()==1&&ct[0].normal.y< -ratio(999,1000),"segment middle hits box, neither endpoint sphere reaches");near(ct[0].penetration,ratio(5,100));
    DeterministicSession corner(sessionConfig());require(installDetRigidBody3D(corner,c)&&corner.addEntity(1,detRigidBodyActor3D(c,capsule(ratio(2,5),D::fromInt(1)),{ratio(9,10),D{},ratio(9,10)}))&&corner.addEntity(2,detRigidBodyActor3D(c,box({ratio(1,2),ratio(1,2),ratio(1,2)})))&&corner.seal(),"capsule corner setup");require(detRigidContacts3D(*corner.checkpoint(),c).empty(),"capsule AABB corner false positive rejected");
    DeterministicSession degenerate(sessionConfig());require(installDetRigidBody3D(degenerate,c)&&degenerate.addEntity(1,detRigidBodyActor3D(c,capsule(ratio(1,2),D{})))&&degenerate.addEntity(2,detRigidBodyActor3D(c,sphere(ratio(1,2)),{ratio(3,4),D{},D{}}))&&degenerate.seal(),"zero segment capsule");ct=detRigidContacts3D(*degenerate.checkpoint(),c);near(ct.at(0).penetration,ratio(1,4));
    c.substeps=1;DeterministicSession inertia(sessionConfig());auto body=capsule(D::fromInt(1),D::fromInt(1),true);body.mass=D::fromInt(10);body.mask=0;
    auto initialPose=detRigidBodyActor3D(c,body,V::fromInts(2,3,4));require(initialPose.pose.position==initialPose.pose.previousPosition,"fresh pose interpolation initialization");
    require(installDetRigidBody3D(inertia,c)&&inertia.addEntity(1,detRigidBodyActor3D(c,body))&&inertia.registerSystem(1,0,[c](DetTickContext& ctx){detRigidBodyForce3D(ctx,c,1,{},V::fromInts(1,1,0));return true;})&&inertia.seal(),"capsule inertia setup");advance(inertia,1);near(state(*inertia.checkpoint(),1,c,6).y,ratio(5,1472),ratio(1,1000000));near(state(*inertia.checkpoint(),1,c,6).x,ratio(5,3872),ratio(1,1000000));
    c.gravity=V::fromInts(0,-10,0);DeterministicSession floor(sessionConfig());require(installDetRigidBody3D(floor,c)&&floor.addEntity(1,detRigidBodyActor3D(c,box(V::fromInts(5,1,5)),V::fromInts(0,-1,0)))&&floor.addEntity(2,detRigidBodyActor3D(c,capsule(ratio(1,2),D::fromInt(1),true),{D{},ratio(3,2),D{}}))&&floor.seal(),"capsule floor");advance(floor,48);require(position(*floor.checkpoint(),2).y>ratio(148,100)&&position(*floor.checkpoint(),2).y<ratio(152,100),"capsule floor support");
}
void drivenJoints(){for(auto kind:{DetJointKind3D::Hinge,DetJointKind3D::Slider}){DetRigidBody3DConfig c;c.gravity={};c.substeps=1;c.velocityIterations=12;c.positionIterations=6;DetRigidJoint3D j;j.id=1;j.kind=kind;j.first=1;j.second=2;j.motor=true;j.targetSpeed=D::fromInt(1);j.maxMotorForce=D::fromInt(10);j.limits=true;j.lower=D{};j.upper=ratio(1,4);c.joints={j};
    auto setup=[&](DeterministicSession& s,bool reverse){auto fixed=box(V::fromInts(1,1,1));fixed.mask=0;auto driven=box(V::fromInts(1,1,1),true);driven.mask=0;return installDetRigidBody3D(s,c)&&(reverse?(s.addEntity(2,detRigidBodyActor3D(c,driven))&&s.addEntity(1,detRigidBodyActor3D(c,fixed))):(s.addEntity(1,detRigidBodyActor3D(c,fixed))&&s.addEntity(2,detRigidBodyActor3D(c,driven))))&&s.seal();};
    DeterministicSession s(sessionConfig()),other(sessionConfig());require(setup(s,false)&&setup(other,true),"driven joint setup");std::optional<DetSessionCheckpoint> mid;
    for(unsigned i=0;i<64;++i){advance(s,1);advance(other,1);require(encodeDetCheckpoint(*s.checkpoint())==encodeDetCheckpoint(*other.checkpoint()),"joint stable insertion order");if(i==31)mid=s.checkpoint();}
    auto cp=*s.checkpoint();auto q=Q::fromBits(cp.actors.at(2).pose.rotation);D coordinate=kind==DetJointKind3D::Hinge?D::fromInt(2)*ayt::math::detAtan2(q.y,q.w):position(cp,2).y;
    near(coordinate,ratio(1,4),ratio(1,100));near(position(cp,2).x,D{});near(position(cp,2).z,D{});if(kind==DetJointKind3D::Hinge){near(q.x,D{});near(q.z,D{});}else near(q.w,D::fromInt(1));
    auto bytes=encodeDetCheckpoint(cp);require(s.restore(*mid),"driven joint restore");advance(s,32);require(encodeDetCheckpoint(*s.checkpoint())==bytes,"motor/limit complete restore suffix");
    auto bad=cp;bad.globals.at(c.jointSchema).back()^=1;require(!s.restore(bad)&&encodeDetCheckpoint(*s.checkpoint())==bytes,"immutable joint policy rejected atomically");
    j.maxMotorForce=D::fromInt(1);j.limits=false;j.lower=j.upper=D{};c.joints={j};DeterministicSession first(sessionConfig());auto fixed=box(V::fromInts(1,1,1));fixed.mask=0;auto driven=box(V::fromInts(1,1,1),true);driven.mass=D::fromInt(2);driven.mask=0;
    require(installDetRigidBody3D(first,c)&&first.addEntity(1,detRigidBodyActor3D(c,fixed))&&first.addEntity(2,detRigidBodyActor3D(c,driven))&&first.seal(),"force-limited motor setup");advance(first,1);near(state(*first.checkpoint(),2,c,kind==DetJointKind3D::Hinge?6:5).y,kind==DetJointKind3D::Hinge?ratio(3,256):ratio(1,128),ratio(1,1000000));
    }
    DetRigidBody3DConfig eight;eight.gravity={};for(unsigned i=1;i<=8;++i){DetRigidJoint3D j;j.id=i;j.kind=DetJointKind3D::Slider;j.first=1;j.second=2;eight.joints.push_back(j);}DeterministicSession s(sessionConfig());auto fixed=box(V::fromInts(1,1,1));fixed.mask=0;auto dynamic=box(V::fromInts(1,1,1),true);dynamic.mask=0;require(installDetRigidBody3D(s,eight)&&s.addEntity(1,detRigidBodyActor3D(eight,fixed))&&s.addEntity(2,detRigidBodyActor3D(eight,dynamic))&&s.seal(),"eight joint bounded schema fits128 fields");
    eight.joints.front().limits=true;eight.joints.front().lower=D::fromInt(2);eight.joints.front().upper=D::fromInt(1);DeterministicSession invalid(sessionConfig());require(!installDetRigidBody3D(invalid,eight),"invalid joint limits rejected");
}
void continuous(){for(bool elastic:{false,true}){DetRigidBody3DConfig c;c.gravity={};c.substeps=1;DeterministicSession s(sessionConfig());auto ball=sphere(ratio(1,4),true);ball.continuous=true;ball.velocity=V::fromInts(640,0,0);ball.restitution=elastic?D::fromInt(1):D{};auto wall=box({ratio(1,50),D::fromInt(2),D::fromInt(2)});wall.restitution=ball.restitution;
    require(installDetRigidBody3D(s,c)&&s.addEntity(1,detRigidBodyActor3D(c,ball,V::fromInts(-5,0,0)))&&s.addEntity(2,detRigidBodyActor3D(c,wall))&&s.seal(),"CCD thin wall setup");auto initial=*s.checkpoint();auto bytes=encodeDetCheckpoint(initial);auto hit=detRigidSphereSweep3D(initial,c,1,V::fromInts(10,0,0));require(bool(hit)&&hit->target==2&&hit->normal==V::fromInts(1,0,0),"sphere sweep actual target normal");near(hit->fraction,(D::fromInt(5)-ratio(27,100)-c.continuousSlop)/D::fromInt(10),ratio(1,100000));require(encodeDetCheckpoint(*s.checkpoint())==bytes,"sweep pure checkpoint query");advance(s,1);auto cp=*s.checkpoint();near(state(cp,1,c,5).x,D::fromInt(elastic?-640:0));near(position(cp,1).x,elastic?ratio(-554,100):ratio(-27,100),ratio(1,1000));auto final=encodeDetCheckpoint(cp);require(s.restore(initial),"CCD restore");advance(s,1);require(encodeDetCheckpoint(*s.checkpoint())==final,"CCD exact restore suffix");
    auto narrow=c;narrow.maxSweepIterations=1;DeterministicSession q(sessionConfig());require(installDetRigidBody3D(q,narrow)&&q.addEntity(1,detRigidBodyActor3D(narrow,ball,V::fromInts(-5,0,0)))&&q.addEntity(2,detRigidBodyActor3D(narrow,wall))&&q.seal(),"sweep budget setup");auto before=encodeDetCheckpoint(*q.checkpoint());bool rejected=false;try{(void)detRigidSphereSweep3D(*q.checkpoint(),narrow,1,V::fromInts(10,0,0));}catch(...){rejected=true;}require(rejected&&encodeDetCheckpoint(*q.checkpoint())==before,"sweep exhausted budget rejects without mutation");
    }
    DetRigidBody3DConfig c;c.gravity={};c.substeps=1;DeterministicSession capsuleTarget(sessionConfig());auto ball=sphere(ratio(1,4),true);ball.continuous=true;ball.velocity=V::fromInts(0,0,640);
    require(installDetRigidBody3D(capsuleTarget,c)&&capsuleTarget.addEntity(1,detRigidBodyActor3D(c,ball,V::fromInts(0,0,-5)))&&capsuleTarget.addEntity(2,detRigidBodyActor3D(c,capsule(ratio(1,4),D::fromInt(1))))&&capsuleTarget.seal(),"CCD capsule target");advance(capsuleTarget,1);near(position(*capsuleTarget.checkpoint(),1).z,ratio(-1,2),ratio(1,1000));near(state(*capsuleTarget.checkpoint(),1,c,5).z,D{});
    DeterministicSession corner(sessionConfig());ball.velocity={};ball.continuous=false;require(installDetRigidBody3D(corner,c)&&corner.addEntity(1,detRigidBodyActor3D(c,ball,{D::fromInt(-5),ratio(13,10),ratio(13,10)}))&&corner.addEntity(2,detRigidBodyActor3D(c,box(V::fromInts(1,1,1))))&&corner.seal(),"CCD corner miss setup");require(!detRigidSphereSweep3D(*corner.checkpoint(),c,1,V::fromInts(10,0,0)),"rounded box corner miss, expanded AABB would hit");
    DeterministicSession pairs(sessionConfig());auto a=sphere(ratio(1,4),true),b=a;a.continuous=b.continuous=true;a.velocity=V::fromInts(320,0,0);b.velocity=V::fromInts(-320,0,0);a.restitution=b.restitution=D::fromInt(1);
    require(installDetRigidBody3D(pairs,c)&&pairs.addEntity(1,detRigidBodyActor3D(c,a,V::fromInts(-2,0,0)))&&pairs.addEntity(2,detRigidBodyActor3D(c,b,V::fromInts(2,0,0)))&&pairs.seal(),"relative dynamic sphere CCD");advance(pairs,1);near(state(*pairs.checkpoint(),1,c,5).x,D::fromInt(-320));near(state(*pairs.checkpoint(),2,c,5).x,D::fromInt(320));require(position(*pairs.checkpoint(),1).x<position(*pairs.checkpoint(),2).x,"relative CCD prevents crossing");
    c.maxContinuousHits=1;DeterministicSession budget(sessionConfig());a.velocity=V::fromInts(1024,0,0);a.half={ratio(1,10),ratio(1,10),ratio(1,10)};auto wall=box({ratio(1,20),D::fromInt(2),D::fromInt(2)});wall.restitution=D::fromInt(1);
    require(installDetRigidBody3D(budget,c)&&budget.addEntity(1,detRigidBodyActor3D(c,a))&&budget.addEntity(2,detRigidBodyActor3D(c,wall,V::fromInts(-1,0,0)))&&budget.addEntity(3,detRigidBodyActor3D(c,wall,V::fromInts(1,0,0)))&&budget.seal(),"CCD hit budget setup");auto initial=*budget.checkpoint();require(!budget.advance({0,1,{}}),"exhausted impact budget fails tick");require(budget.restore(initial)&&encodeDetCheckpoint(*budget.checkpoint())==encodeDetCheckpoint(initial),"explicit restore after failed CCD");
}
void rollbackAndAdmission(){DetRigidBody3DConfig c;c.gravity={};c.substeps=1;auto setup=[c](DeterministicSession& s){auto ball=sphere(ratio(1,4),true);ball.continuous=true;ball.velocity=V::fromInts(640,0,0);auto wall=box({ratio(1,50),D::fromInt(2),D::fromInt(2)});
    return installDetRigidBody3D(s,c)&&s.addEntity(10,detRigidBodyActor3D(c,ball,V::fromInts(-35,0,0)))&&s.addEntity(20,detRigidBodyActor3D(c,wall))&&s.registerSystem(1,0,[c](DetTickContext& ctx){for(const auto& cmd:ctx.input().commands){if(cmd.type!=82||cmd.payload.size()!=1)return false;detRigidBodyForce3D(ctx,c,10,V::fromInts(0,cmd.payload[0]?128:0,0));}return true;})&&s.seal();};
    DeterministicSession truth(sessionConfig()),predicted(sessionConfig());require(setup(truth)&&setup(predicted),"CCD rollback setup");DetRollbackConfig rc;rc.members={1,2};rc.prediction={{82,DetPredictionMode::Hold}};DeterministicRollback rollback(predicted,rc);
    auto input=[](unsigned t){return DetTickInput{t,1,{{2,0,82,{static_cast<std::uint8_t>(t==3)}}}};};for(unsigned t=0;t<8;++t){require(truth.advance(input(t)),"CCD rollback truth");require(rollback.submit(1,{t,1,{}}),"CCD local input");if(t!=3)require(rollback.submit(2,input(t)),"CCD actual remote input");if(!rollback.advance())throw std::runtime_error(rollback.error());if(t==5)require(rollback.submit(2,input(3)),"CCD delayed input");}
    require(rollback.rollbackCount()>0&&encodeDetCheckpoint(*truth.checkpoint())==encodeDetCheckpoint(*predicted.checkpoint()),"CCD actual late-input complete rollback equality");
    auto ball=sphere(ratio(1,4),true);ball.continuous=true;DeterministicSession unsupported(sessionConfig());require(installDetRigidBody3D(unsupported,c)&&unsupported.addEntity(1,detRigidBodyActor3D(c,ball))&&unsupported.addEntity(2,detRigidBodyActor3D(c,box(V::fromInts(1,1,1),true),V::fromInts(5,0,0))),"unsupported CCD setup");require(!unsupported.seal(),"CCD dynamic box admission rejected");
    DeterministicSession sensor(sessionConfig());ball.continuous=false;auto volume=box(V::fromInts(1,1,1));volume.trigger=true;require(installDetRigidBody3D(sensor,c)&&sensor.addEntity(1,detRigidBodyActor3D(c,ball,V::fromInts(-5,0,0)))&&sensor.addEntity(2,detRigidBodyActor3D(c,volume))&&sensor.seal(),"sweep sensor setup");require(!detRigidSphereSweep3D(*sensor.checkpoint(),c,1,V::fromInts(10,0,0))&&detRigidSphereSweep3D(*sensor.checkpoint(),c,1,V::fromInts(10,0,0),true),"explicit sweep sensor participation");
}
void exactPosePublication(){DetRigidBody3DConfig c;c.gravity={};c.substeps=1;bool nonIdempotent=false;
    for(unsigned i=1;i<=32;++i){auto q=Q::fromAxisAngle(V::fromInts(1,2,3),ratio(i,19));require(bool(q),"publication rotation authoring");auto body=sphere(D::fromInt(1),true);body.mask=0;body.angularVelocity=V::fromInts(3,-2,1)*ratio(1,16);
        DeterministicSession s(sessionConfig());require(installDetRigidBody3D(s,c)&&s.addEntity(1,detRigidBodyActor3D(c,body,{},*q))&&s.seal(),"publication setup");auto before=Q::fromBits(s.checkpoint()->actors.at(1).pose.rotation);advance(s,1);auto cp=*s.checkpoint();auto expected=before.integratedAngularVelocityWorld(state(cp,1,c,6),ratio(1,64));require(bool(expected),"publication reference");
        nonIdempotent|=expected->bits()!=expected->normalized()->bits();require(cp.actors.at(1).pose.rotation==expected->bits(),"published pose preserves exact solver rotation, no extra normalization");}
    require(nonIdempotent,"publication fixture exposes normalization bit drift");
}
int main(){try{capsuleGeometry();drivenJoints();continuous();rollbackAndAdmission();exactPosePublication();std::cout<<"PASS capsule geometry/inertia, hinge/slider motor and limits, frozen sphere sweep, relative sphere CCD, restore/rollback, exact pose publication and admission/budget checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
